async function playerDetail(db2, id) {
  const p = await db2.one(
    "SELECT p.id, p.email, p.name, p.mobile, p.office_address, p.registered_at, p.registration_credits, o.name_en AS office, o.city, o.state FROM players p LEFT JOIN offices o ON o.id=p.office_id WHERE p.id=$1",
    [id]
  );
  if (!p) return null;
  const list = (await listPlayers(db2)).find((x) => x.id === id);
  const attempts = await db2.query(
    `SELECT a.id, a.round_key, a.chance_no, a.page_id, pg.label AS page_label, a.started_at, a.deadline_at, a.submitted_at, a.status, a.auto_submitted,
            a.score, a.measures, a.left_page_count, a.paste_blocked_count, a.chat_count, a.session_id,
            (SELECT count(*)::int FROM attempt_events e WHERE e.attempt_id=a.id) AS events
     FROM attempts a LEFT JOIN pages pg ON pg.id=a.page_id WHERE a.player_id=$1 ORDER BY a.started_at DESC`,
    [id]
  );
  const chat = await db2.one("SELECT count(*)::int AS n, count(*) FILTER (WHERE blocked)::int AS blocked FROM chat_logs WHERE player_id=$1", [id]);
  const name2 = (k) => config().rounds.find((r) => r.key === k)?.nameEn ?? k;
  return {
    ...list,
    officeAddress: p.office_address,
    registrationCredits: Number(p.registration_credits),
    chat: chat ?? { n: 0, blocked: 0 },
    history: attempts.map((a) => ({
      id: a.id,
      roundKey: a.round_key,
      roundName: name2(a.round_key),
      chanceNo: a.chance_no,
      page: a.page_label ?? a.page_id,
      startedAt: a.started_at,
      submittedAt: a.submitted_at,
      status: a.status,
      autoSubmitted: a.auto_submitted,
      score: a.score,
      minutes: a.submitted_at ? Math.round((+new Date(a.submitted_at) - +new Date(a.started_at)) / 6e3) / 10 : null,
      measures: a.measures,
      leaves: a.left_page_count,
      pasteBlocks: a.paste_blocked_count,
      chat: a.chat_count,
      events: a.events,
      sessionId: a.session_id
    }))
  };
}
async function resetPlayer(db2, id, deletePlayer) {
  return db2.tx(async (q) => {
    const p = await q.one("SELECT email FROM players WHERE id=$1", [id]);
    if (!p) return null;
    const ev = await q.one("SELECT count(*)::int AS n FROM attempt_events WHERE attempt_id IN (SELECT id FROM attempts WHERE player_id=$1)", [id]);
    await q.query("DELETE FROM attempt_events WHERE attempt_id IN (SELECT id FROM attempts WHERE player_id=$1)", [id]);
    const at = await q.query("DELETE FROM attempts WHERE player_id=$1 RETURNING id", [id]);
    const ch = await q.query("DELETE FROM chat_logs WHERE player_id=$1 RETURNING id", [id]);
    if (deletePlayer) {
      await q.query("DELETE FROM players WHERE id=$1", [id]);
      await q.query("DELETE FROM otp_challenges WHERE email=$1", [p.email]);
    }
    return { email: p.email, attempts: at.length, events: ev?.n ?? 0, chats: ch.length, playerDeleted: deletePlayer };
  });
}
async function resetAllPlayData(db2) {
  return db2.tx(async (q) => {
    const n = async (t) => (await q.one(`SELECT count(*)::int AS n FROM ${t}`))?.n ?? 0;
    const counts = { players: await n("players"), attempts: await n("attempts"), events: await n("attempt_events"), chats: await n("chat_logs"), xlitStats: await n("xlit_stats") };
    await q.query("DELETE FROM attempt_events");
    await q.query("DELETE FROM attempts");
    await q.query("DELETE FROM chat_logs");
    await q.query("DELETE FROM xlit_stats");
    await q.query("DELETE FROM otp_challenges");
    await q.query("DELETE FROM players");
    return counts;
  });
}

