var RESET_ALL_PHRASE = "RESET ALL TEST DATA";
var audit = (db2, actor, action, target, meta) => db2.query("INSERT INTO audit_logs (actor, action, target, meta) VALUES ($1,$2,$3,$4)", [actor, action, target, meta ? JSON.stringify(meta) : null]);
