  app2.post("/admin/pages/:id/draft", async (req, reply) => {
    const who = manager(req, reply);
    if (!who) return;
    const { id } = parse2(external_exports.object({ id: external_exports.string() }), req.params);
    const { overwrite } = parse2(external_exports.object({ overwrite: external_exports.boolean().default(false) }), req.body);
    const p = await loadPage(db2, id);
    if (!p) return reply.code(404).send({ error: "not_found" });
    if (!isConfigured("translation")) return reply.code(503).send({ error: "nmt_not_configured" });
    const page = structuredClone(p.page);
    const targets = page.parts.flatMap((part) => part.editable ? part.fields.filter((f) => !f.numeric && f.en && (overwrite || !f.draft)).map((f) => ({ part, f })) : []);
    const out = await translateBatch(targets.map(({ f }) => ({ text: f.en, locked: f.locked })));
    const lost = [];
    targets.forEach(({ part, f }, i) => {
      f.draft = out[i].text;
      if (out[i].lost) lost.push(`${part.id}.${f.key}`);
    });
    const row = await db2.one("SELECT sector, source, sample FROM pages WHERE id=$1", [id]);
    await savePage(db2, page, { sector: row.sector, source: row.source, sample: row.sample });
    await audit(db2, who, "page.draft", id, { fields: targets.length, lost });
    return { ok: true, translated: targets.length, needsManualFix: lost };
  });
