      const where = `(lower(en) LIKE $1 OR hi LIKE $2 OR EXISTS (SELECT 1 FROM unnest(accepted_variants) v WHERE v LIKE $2))
        AND ($3::boolean = false OR cardinality(flags) > 0 OR override IS NOT NULL)`;
