    if (!isConfigured("tts")) return reply.code(503).send({ error: "tts_not_configured" });
    const dir = resolve7(ROOT, ".data/audio");
    mkdirSync2(dir, { recursive: true });
    let ok = 0, failed = 0;
    const hi = config().bhashiniServices.ttsLanguage === "hi";
